CREATE TABLE public.venta (
    id_venta integer NOT NULL,
    id_turno integer NOT NULL,
    id_cliente integer,
    id_cupon integer,
    fecha_hora timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    subtotal_iva_0 numeric(10,2) DEFAULT 0 NOT NULL,
    subtotal_iva_15 numeric(10,2) DEFAULT 0 NOT NULL,
    monto_iva numeric(10,2) DEFAULT 0 NOT NULL,
    total_factura numeric(10,2) DEFAULT 0 NOT NULL,
    monto_recibido numeric(10,2) DEFAULT 0 NOT NULL,
    cambio numeric(10,2) DEFAULT 0 NOT NULL,
    anulada boolean DEFAULT false NOT NULL
);


